"""Table transforms for explode/implode commands.

The CLI layer owns argument parsing and CSV I/O; these helpers accept a header
and string rows and return transformed header and rows.
"""

def _singular(name):
    # Xan documents this as deliberately simple English-centric plural handling.
    if name.endswith("ies") and len(name) > 3:
        return name[:-3] + "y"
    if name.endswith("ses") and len(name) > 3:
        return name[:-2]
    if name.endswith("s") and not name.endswith("ss") and len(name) > 1:
        return name[:-1]
    return name


def explode(headers, rows, indices, sep="|", rename=None, singularize=False,
            drop_empty=False):
    """Split aligned cells in selected columns, duplicating other cells.

    Raises ValueError on rows whose selected columns split into unequal lengths.
    """
    indices = list(indices)
    out_headers = list(headers)
    if rename is not None:
        names = list(rename)
        if len(names) != len(indices):
            raise ValueError("wrong number of rename values")
        for i, name in zip(indices, names):
            out_headers[i] = name
    elif singularize:
        for i in indices:
            out_headers[i] = _singular(out_headers[i])
    out = []
    for row in rows:
        row = list(row)
        if not indices:
            out.append(row)
            continue
        parts = [row[i].split(sep) for i in indices]
        sizes = {len(p) for p in parts}
        if len(sizes) > 1:
            raise ValueError("inconsistent exploded length across columns")
        for values in zip(*parts):
            if drop_empty and any(v == "" for v in values):
                continue
            new = row[:]
            for i, value in zip(indices, values):
                new[i] = value
            out.append(new)
    return out_headers, out


def implode(headers, rows, indices, sep="|", rename=None, pluralize=False,
            compare_indices=None):
    """Merge consecutive identical rows except selected diverging columns."""
    indices = list(indices)
    if not indices:
        return list(headers), [list(r) for r in rows]
    out_headers = list(headers)
    if rename is not None:
        if len(indices) != 1:
            raise ValueError("rename for multiple columns requires matching names")
        out_headers[indices[0]] = rename
    elif pluralize:
        for i in indices:
            out_headers[i] = _plural(out_headers[i])
    compare = set(range(len(headers))) - set(indices) if compare_indices is None else set(compare_indices)
    out = []
    for source in rows:
        row = list(source)
        if out and all(out[-1][i] == row[i] for i in compare):
            for i in indices:
                out[-1][i] += sep + row[i]
        else:
            out.append(row)
    return out_headers, out


def _plural(name):
    if name.endswith("y") and len(name) > 1 and name[-2].lower() not in "aeiou":
        return name[:-1] + "ies"
    if name.endswith(("s", "x", "z", "ch", "sh")):
        return name + "es"
    return name + "s"
